    { chunkX: 2, chunkY: 0 },
    { chunkX: -2, chunkY: 0 },
    { chunkX: 0, chunkY: 2 },
    { chunkX: 0, chunkY: -2 },
  ];
  for (const candidate of fallback) {
    if (candidates.length >= needed) break;
